# feature-group.tf -- Online e Offline Store nascem na MESMA declaracao

resource "aws_sagemaker_feature_group" "media_pedidos_30d" {
  feature_group_name             = "${var.projeto}-media-pedidos-30d"
  record_identifier_feature_name = "loja_sku_id"
  event_time_feature_name        = "calculado_em"
  role_arn                        = aws_iam_role.feature_store_ingestao.arn

  feature_definition {
    feature_name = "loja_sku_id"
    feature_type = "String"
  }
  feature_definition {
    feature_name = "loja_id"
    feature_type = "String"
  }
  feature_definition {
    feature_name = "produto_id"
    feature_type = "String"
  }
  feature_definition {
    feature_name = "media_pedidos_30d"
    feature_type = "Fractional"
  }
  feature_definition {
    feature_name = "calculado_em"
    feature_type = "String"
  }

  # ONLINE: baixa latencia, so o valor mais recente por chave.
  online_store_config {
    enable_online_store = true
    security_config {
      kms_key_id = aws_kms_key.feature_store.arn
    }
  }

  # OFFLINE: historico completo, particionado, para o join ponto-no-tempo.
  # Confira os nomes exatos dos blocos aninhados na versao do provider AWS
  # que voce usa -- este recurso evoluiu bastante entre versoes.
  offline_store_config {
    s3_storage_config {
      s3_uri     = "s3://${var.bucket_lake}/feature-store/media-pedidos-30d/"
      kms_key_id = aws_kms_key.feature_store.arn
    }
    disable_glue_table_creation = false
  }

  tags = {
    Projeto = var.projeto
    Time    = "dados"
    Consome = "modelo-reposicao"
  }
}

resource "aws_kms_key" "feature_store" {
  description             = "Chave unica para Online e Offline Store de features da Cadencia"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

// RecomendarReposicaoHandler.cs -- le a MESMA feature que o treino usou,
// via Online Store, e nunca recalcula media_pedidos_30d na mao.

using Amazon.SageMakerFeatureStoreRuntime;
using Amazon.SageMakerFeatureStoreRuntime.Model;
using Amazon.SageMakerRuntime;
using Amazon.SageMakerRuntime.Model;
using Microsoft.Extensions.Http.Resilience;
using Polly;

namespace Cadencia.Reposicao;

public record PedidoDeReposicao(string LojaId, string ProdutoId, decimal PrecoVenda);

public class RecomendarReposicaoHandler
{
    private readonly AmazonSageMakerFeatureStoreRuntimeClient _featureStore;
    private readonly AmazonSageMakerRuntimeClient _endpoint;
    private readonly ResiliencePipeline _resiliencia;
    private const string FeatureGroup = "cadencia-media-pedidos-30d";
    private const string EndpointModelo = "cadencia-modelo-reposicao";

    public RecomendarReposicaoHandler(
        AmazonSageMakerFeatureStoreRuntimeClient featureStore,
        AmazonSageMakerRuntimeClient endpoint)
    {
        _featureStore = featureStore;
        _endpoint = endpoint;

        // Retry com backoff E jitter -- retry sem jitter transforma
        // instabilidade em apagao sincronizado (assunto do L36).
        _resiliencia = new ResiliencePipelineBuilder()
            .AddRetry(new Polly.Retry.RetryStrategyOptions
            {
                MaxRetryAttempts = 3,
                BackoffType = DelayBackoffType.Exponential,
                UseJitter = true,
                Delay = TimeSpan.FromMilliseconds(50),
            })
            .AddTimeout(TimeSpan.FromMilliseconds(200))
            .Build();
    }

    public async Task<double> RecomendarAsync(PedidoDeReposicao pedido)
    {
        var lojaSkuId = $"{pedido.LojaId}#{pedido.ProdutoId}";

        // 1. LE a feature -- nao recalcula. Se o registro nao existir ainda
        //    (SKU novo, sem 30 dias de historico), o fallback e decisao de
        //    produto, nao deste modulo: normalmente comeca em zero.
        var registro = await _resiliencia.ExecuteAsync(async ct =>
            await _featureStore.GetRecordAsync(new GetRecordRequest
            {
                FeatureGroupName = FeatureGroup,
                RecordIdentifierValueAsString = lojaSkuId,
            }, ct));

        var mediaPedidos30d = registro.Record?
            .FirstOrDefault(f => f.FeatureName == "media_pedidos_30d")
            ?.ValueAsString is { } valor ? double.Parse(valor) : 0.0;

        // 2. Invoca o endpoint com a MESMA feature que o treino usaria para
        //    esta chave, nao uma reimplementacao da formula.
        var payload = System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(new
        {
            preco_venda = pedido.PrecoVenda,
            media_pedidos_30d = mediaPedidos30d,
        });

        var resposta = await _resiliencia.ExecuteAsync(async ct =>
            await _endpoint.InvokeEndpointAsync(new InvokeEndpointRequest
            {
                EndpointName = EndpointModelo,
                ContentType = "application/json",
                Body = new MemoryStream(payload),
            }, ct));

        using var leitor = new StreamReader(resposta.Body);
        return double.Parse(await leitor.ReadToEndAsync());
    }

    // /health nunca toca a AWS -- so confirma que o processo esta de pe.
    // /ready confirma Feature Store e endpoint alcancaveis; sao perguntas
    // diferentes, e confundi-las derruba a instancia sadia quando a AWS oscila.
    public bool Health() => true;

    public async Task<bool> ReadyAsync()
    {
        try
        {
            await _featureStore.GetRecordAsync(new GetRecordRequest
            {
                FeatureGroupName = FeatureGroup,
                RecordIdentifierValueAsString = "sonda#sonda",
            });
            return true;
        }
        catch (ResourceNotFoundException)
        {
            // registro de sonda nao existe -- e RESPOSTA valida, o servico
            // alcancou o Feature Store com sucesso.
            return true;
        }
        catch
        {
            return false;
        }
    }
}
